def load_cases(path: str | Path) -> list[BenchCase]:
    cases = []
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        if line.strip():
            d = json.loads(line)
            cases.append(BenchCase(**{k: d.get(k) for k in BenchCase.__dataclass_fields__}))
    return cases
